  const [selectedId, setSelectedId] = useState<string | null>(null); const [drafts, setDrafts] = useState<Record<string, HousekeepingDraft>>({}); const [mobileFocus, setMobileFocus] = useState(false); const [isMobile, setIsMobile] = useState(() => window.innerWidth < 768); const [lastUpdated, setLastUpdated] = useState("");
