  useEffect(() => { void load(new URLSearchParams(location.search).get("date") ?? boardDate); }, []); useEffect(() => { const onResize = () => setIsMobile(window.innerWidth < 768); window.addEventListener("resize", onResize); return () => window.removeEventListener("resize", onResize); }, []);
  const visible = filterHousekeepingQueue(buildHousekeepingQueue(board.rooms, board.departures_today), filter, search);
  useEffect(() => { if (visible.length && !visible.some(room => room.room_id === selectedId)) setSelectedId(visible[0].room_id); }, [visible, selectedId]);
  const selected = visible.find(room => room.room_id === selectedId) ?? visible[0]; const draftFor = (roomId: string) => drafts[roomId] ?? newHousekeepingDraft(); const draft = selected ? draftFor(selected.room_id) : newHousekeepingDraft();
