const navigation = [["bookings", "/bookings", "Recepción", "Llegadas, salidas y cobros"], ["rooms", "/rooms", "Habitaciones", "Inventario y disponibilidad"], ["guests", "/guests", "Huéspedes", "Fichas y contactos"], ["housekeeping", "/housekeeping", "Housekeeping", "Limpieza y handoff"], ["reports", "/reports", "Reportes", "Ocupación e ingresos"], ["users", "/users", "Usuarios", "Accesos y roles"], ["network", "/network", "Red", "Operación multi-hotel"]] as const;

type ActiveAuth = { hotel_id: string | null; hotel_name: string | null };
const hotelLabels: Record<string, string> = {
  "10000000-0000-0000-0000-000000000001": "Hotel Norte",
  "20000000-0000-0000-0000-000000000002": "Hotel Sur",
};

export function App() {
  const [identityVersion, setIdentityVersion] = useState(0); const [mobileNavOpen, setMobileNavOpen] = useState(false); const [activeHotelLabel, setActiveHotelLabel] = useState("Cargando…");
  const mobileNavRef = useRef<HTMLDialogElement | null>(null); const mobileMenuTriggerRef = useRef<HTMLButtonElement | null>(null); const activeHotelRequestRef = useRef(0);
  const page = location.pathname.startsWith("/guests") ? "guests" : location.pathname.startsWith("/rooms") ? "rooms" : location.pathname.startsWith("/housekeeping") ? "housekeeping" : location.pathname.startsWith("/users") ? "users" : location.pathname.startsWith("/network") ? "network" : location.pathname.startsWith("/reports") ? "reports" : "bookings";
  const activeLabel = navigation.find(([key]) => key === page)?.[2] ?? "Recepción";
  function closeMobileNav() { setMobileNavOpen(false); requestAnimationFrame(() => mobileMenuTriggerRef.current?.focus()); }
  useEffect(() => { const requestId = ++activeHotelRequestRef.current; setActiveHotelLabel("Cargando…"); void api<ActiveAuth>("/auth/me").then(({ hotel_id, hotel_name }) => { if (requestId === activeHotelRequestRef.current) setActiveHotelLabel(hotel_name ?? hotelLabels[hotel_id ?? ""] ?? "Hotel"); }).catch(() => { if (requestId === activeHotelRequestRef.current) setActiveHotelLabel("Hotel"); }); }, [identityVersion]);
  useEffect(() => { if (!mobileNavOpen) return; const closeOnDesktop = () => { if (window.innerWidth > 900) closeMobileNav(); }; window.addEventListener("resize", closeOnDesktop); return () => window.removeEventListener("resize", closeOnDesktop); }, [mobileNavOpen]);
  const content = page === "rooms" ? <Rooms /> : page === "guests" ? <Guests /> : page === "housekeeping" ? <HousekeepingRework /> : page === "users" ? <UsersAdmin /> : page === "network" ? <NetworkAdmin /> : page === "reports" ? <Reports /> : <><Bookings /><BillingPanel /><CashBalancePanel /></>;
  const navLinks = (close = false) => navigation.map(([key, href, label, description]) => <a key={key} className={page === key ? "active" : ""} href={href} onClick={close ? closeMobileNav : undefined}><strong>{label}</strong><small>{description}</small></a>);
  useLayoutEffect(() => {
    const dialog = mobileNavRef.current;
    if (!dialog) return;
    if (mobileNavOpen) {
      if (!dialog.open) dialog.showModal();
      const firstFocusable = dialog.querySelector<HTMLElement>("a, button");
      firstFocusable?.focus();
      const onCancel = (event: Event) => { event.preventDefault(); closeMobileNav(); };
      dialog.addEventListener("cancel", onCancel);
      return () => dialog.removeEventListener("cancel", onCancel);
    }
    if (dialog.open) dialog.close();
    mobileMenuTriggerRef.current?.focus();
  }, [mobileNavOpen]);
  function trapMobileNavFocus(event: KeyboardEvent<HTMLDialogElement>) {
    if (event.key !== "Tab") return;
    const focusable = Array.from(event.currentTarget.querySelectorAll<HTMLElement>("a, button")).filter(element => !element.hasAttribute("disabled"));
    if (!focusable.length) return;
    const first = focusable[0]; const last = focusable[focusable.length - 1];
    if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
    else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
  }
  return <div className="app-shell"><aside className="desktop-sidebar" aria-label="Navegación principal"><a className="brand" href="/bookings"><span className="brand-mark">H</span><span><strong>HMS</strong><small>Elite</small></span></a><p className="nav-label">Operación</p><nav>{navLinks()}</nav><div className="sidebar-footer"><span className="status-dot" /> Staging · Access activo</div></aside><main className="app-main"><header className="app-header"><div className="mobile-heading"><button ref={mobileMenuTriggerRef} className="menu-trigger" type="button" aria-label="Abrir navegación" aria-expanded={mobileNavOpen} onClick={() => setMobileNavOpen(true)}>☰</button><div><p className="eyebrow">HMS Elite</p><h1>{activeLabel}</h1></div></div><div className="desktop-heading"><p className="eyebrow">Hotel operations</p><h1>{activeLabel}</h1></div><span className="header-context">{activeHotelLabel} · Operación</span></header><div className="app-content"><LocalDevIdentitySelector onChange={() => setIdentityVersion(value => value + 1)} /><div key={identityVersion}>{content}</div></div></main>{mobileNavOpen && <dialog ref={mobileNavRef} className="mobile-nav" aria-label="Navegación móvil" onKeyDown={trapMobileNavFocus} onClick={event => { if (event.target === event.currentTarget) closeMobileNav(); }}><div className="mobile-nav-heading"><a className="brand" href="/bookings"><span className="brand-mark">H</span><span><strong>HMS</strong><small>Elite</small></span></a><button type="button" className="close-nav" aria-label="Cerrar navegación" onClick={closeMobileNav}>×</button></div><nav>{navLinks(true)}</nav><p className="sidebar-footer"><span className="status-dot" /> {activeHotelLabel} · Access activo</p></dialog>}</div>;
}
